-- pre: DELETE FROM cv_maint WHERE id % 3 = 0;
-- pre: VACUUM cv_maint;
-- pre: INSERT INTO cv_maint SELECT 10000 + i, i % 5, i FROM generate_series(1, 700) i;
-- pre: UPDATE cv_maint SET v = v + 1 WHERE id % 5 = 0;
-- pre: SELECT sift.col_promote('cv_maint_col'), sift.col_merge('cv_maint_col');
-- pre: REINDEX INDEX cv_maint_col;
-- pre: DELETE FROM cv_maint WHERE id > 10000 AND id % 2 = 0;
-- pre: VACUUM cv_maint;
-- pre: INSERT INTO cv_maint SELECT 20000 + i, i % 5, i FROM generate_series(1, 300) i;
SELECT coverage.same('SELECT grp, count(*), sum(v), max(id) FROM cv_maint GROUP BY grp')

-- pre: CREATE TABLE cv_l06a (id int, v int) USING sift_table;
-- pre: COPY cv_l06a FROM PROGRAM 'seq 1 1500 | sed -E "s/(.*)/\1,\1/"' (FORMAT csv);
-- pre: COPY cv_l06a TO PROGRAM 'wc -l >/dev/null' (FORMAT csv);
-- pre: CREATE TABLE cv_l06b (id int, v int) USING sift_table;
-- pre: INSERT INTO cv_l06b SELECT i, i * 2 FROM generate_series(1, 1500) i;
-- pre: CREATE TABLE cv_l06c USING sift_table AS SELECT i AS id, i * 3 AS v FROM generate_series(1, 1500) i;
-- pre: CREATE TABLE cv_l06d AS SELECT i AS id, i * 4 AS v FROM generate_series(1, 1500) i;
-- pre: ALTER TABLE cv_l06d SET ACCESS METHOD sift_table;
-- pre: VACUUM cv_l06a, cv_l06b, cv_l06c, cv_l06d;
SELECT bool_and(coverage.same(format('SELECT id %% 7, count(*), sum(v) FROM %s GROUP BY 1', t))) FROM unnest(ARRAY['cv_l06a', 'cv_l06b', 'cv_l06c', 'cv_l06d']) t

-- pre: CREATE TABLE cv_l08 (id int PRIMARY KEY, g int, v int) USING sift_table;
-- pre: INSERT INTO cv_l08 SELECT i, i % 7, i FROM generate_series(1, 2000) i;
-- pre: UPDATE cv_l08 SET v = v + 1 WHERE id % 5 = 0;
-- pre: DELETE FROM cv_l08 WHERE id % 11 = 0;
-- pre: INSERT INTO cv_l08 SELECT i, 1, i FROM generate_series(1, 20) i ON CONFLICT (id) DO UPDATE SET v = excluded.v + 100;
-- pre: BEGIN;
-- pre: SELECT id FROM cv_l08 WHERE id < 5 FOR SHARE;
-- pre: SAVEPOINT s1;
-- pre: UPDATE cv_l08 SET v = -1 WHERE id < 3;
-- pre: ROLLBACK TO s1;
-- pre: SELECT id FROM cv_l08 WHERE id BETWEEN 10 AND 12 FOR UPDATE;
-- pre: COMMIT;
-- pre: CREATE FUNCTION cv_l08_trg() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.v := NEW.v + 1; RETURN NEW; END $$;
-- pre: CREATE TRIGGER cv_l08_t BEFORE UPDATE ON cv_l08 FOR EACH ROW EXECUTE FUNCTION cv_l08_trg();
-- pre: UPDATE cv_l08 SET v = v WHERE id % 13 = 0;
-- pre: CREATE INDEX cv_l08_v ON cv_l08 (v);
-- pre: VACUUM FULL cv_l08;
-- pre: CLUSTER cv_l08 USING cv_l08_v;
SELECT coverage.same('SELECT g, count(*), sum(v), min(v) FROM cv_l08 GROUP BY g')
